function makeConfig(raw) {
  const profile = profiles[raw.moduleNumber];
  const topicDetails = raw.topicDetails || raw.topics.map((topic) => `Define the purpose, inputs, assumptions, implementation, tests, operating evidence, and limitations of ${topic.toLowerCase()}.`);
  const metrics = raw.metrics || [
    { label: "Baseline", value: 52, note: "The simplest valid reference result." },
    { label: "Validated method", value: 76, note: "Measured after controlled implementation and testing." },
    { label: "Monitored release", value: 88, note: "Includes operating, safety, and documentation controls." },
  ];
  const approaches = raw.approaches || raw.topics.slice(0, 4).map((topic, index) => ({
    label: topic,
    symbol: `Option ${index + 1}`,
    meaning: topicDetails[index],
  }));
  const exampleContexts = raw.exampleContexts || raw.topics.slice(0, 8).map((topic, index) => ({
    title: `Apply ${topic}`,
    problem: `${raw.scenario} Focus on ${topic.toLowerCase()}.`,
    steps: ["State the decision and contract.", `Apply ${topic.toLowerCase()} using versioned inputs.`, "Compare with a baseline or known result.", "Test edge cases and preserve evidence."],
    answer: `Use ${topic.toLowerCase()} only after its assumptions, result, and limitations are validated.`,
    interpretation: index === 0 ? raw.expectedInsight : "The method is valuable when it improves the declared decision without hiding risk or uncertainty.",
  }));
  const applications = { ...profile.applications, ...(raw.applications || {}) };

  return {
    ...raw,
    shortTitle: raw.shortTitle || raw.title,
    whyTitle: raw.whyTitle || `Why ${raw.title} Matters`,
    introduction: raw.introduction || `${raw.title} connects analytical technique to a real decision. Learners must understand not only how the method works, but also when it fails, how it is evaluated, and how evidence is communicated.` ,
    centralProblem: raw.centralProblem || raw.scenario,
    investigationTitle: raw.investigationTitle || `Opening Investigation: ${raw.title}`,
    investigationQuestions: raw.investigationQuestions || [
      "What decision and action will this work support?",
      "What exactly are the inputs, outputs, population, and time boundary?",
      "What is the simplest valid baseline?",
      "Which assumptions can fail?",
      "How will leakage, bias, privacy, security, and misuse be prevented?",
      "Which independent evidence is required before release?",
      "What must be monitored after release?",
      "Who owns review, escalation, rollback, and improvement?",
    ],
    expectedInsight: raw.expectedInsight || "A method becomes professional when its decision purpose, assumptions, evaluation, limitations, and operating controls are as explicit as its code.",
    lifecycleTitle: raw.lifecycleTitle || `${raw.title} — End-to-End Lifecycle`,
    feedback: raw.feedback || "Do not advance to release until the current stage has reproducible evidence and an accountable owner.",
    lifecycleInterpretation: raw.lifecycleInterpretation || "The lifecycle prevents a locally impressive result from becoming an unsafe or unsupported production decision.",
    comparisonTitle: raw.comparisonTitle || `${raw.title} — Alternatives and Tradeoffs`,
    approaches,
    metricTitle: raw.metricTitle || `Illustrative ${raw.title} Evidence`,
    metricUnit: raw.metricUnit || "score",
    metrics,
    metricInterpretation: raw.metricInterpretation || "The preferred method must outperform the baseline on decision-relevant evidence, not merely one convenient metric.",
    graphEquation: raw.graphEquation || "evidence score = weighted correctness + reliability + safety + usability",
    graphYLabel: raw.graphYLabel || "Evidence score",
    graphRows: raw.graphRows || metrics.slice(0, 3).map((item, index) => ({ stage: index + 1, score: item.value })),
    prerequisites: raw.prerequisites || profile.prerequisites,
    topicDetails,
    exampleContexts,
    explorationTitle: raw.explorationTitle || `${raw.title} Investigation Studio`,
    explorationPurpose: raw.explorationPurpose || `Build, challenge, and defend a complete ${raw.title.toLowerCase()} workflow.` ,
    applications,
    aiTitle: raw.aiTitle || "AI Can Accelerate the Work, but Evidence and Accountability Remain Human Responsibilities",
    aiExplanation: raw.aiExplanation || "AI can draft code, tests, documentation, and alternatives. Accountable people must approve data meaning, evaluation, safety, permissions, release, and response." ,
    aiUses: raw.aiUses || ["Draft implementation alternatives.", "Generate tests and edge cases.", "Summarize measured diagnostics.", "Draft documentation for human review.", "Identify questions requiring additional evidence."],
    aiCaution: raw.aiCaution || "Never allow AI to invent measurements, expose protected data, approve its own output, bypass independent evaluation, or release material decisions without human authority.",
    aiReflection: raw.aiReflection || "Which steps can be automated safely, and which require accountable domain, statistical, security, legal, or operational judgment?",
    labTitle: raw.labTitle || `${raw.title} Evidence Pack`,
    labDescription: raw.labDescription || "Create a small, reproducible evidence table, five-control validation report, checksum, limitations list, and machine-readable PASS manifest." ,
    labQuestions: raw.labQuestions || ["Which evidence is illustrative?", "Which production measurement should replace it?", "Why is a checksum useful?", "Which control should block release?", "What limitation changes the recommendation?", "How would this lab connect to Fabric, MLflow, or CI/CD?"],
    commonMistakes: raw.commonMistakes || [
      { mistake: "Starting with a tool instead of a decision", correction: "Define the user, action, target, timing, costs, and consequences first." },
      { mistake: "Skipping the baseline", correction: "Create the simplest valid reference so added complexity must earn its place." },
      { mistake: "Using one convenient metric", correction: "Evaluate decision utility, uncertainty, subgroups, failures, safety, latency, and cost." },
      { mistake: "Testing on development evidence", correction: "Protect independent evaluation and document every selection decision." },
      { mistake: "Hiding limitations", correction: "Publish known weaknesses, unsupported uses, owners, and review conditions." },
      { mistake: "Treating deployment as completion", correction: "Monitor real behavior, investigate incidents, and retain rollback and human-review paths." },
    ],
    discussionQuestions: raw.discussionQuestions || ["When is the simplest method preferable?", "Which error is most costly?", "Who can be harmed by a false result?", "What evidence would reverse the recommendation?", "Which decision must remain human?", "How should uncertainty be communicated?", "When should the system stop automatically?", "Who owns the outcome after release?"],
    researchTitle: raw.researchTitle || `Compare Alternative Methods for ${raw.title}`,
    researchDescription: raw.researchDescription || `Compare a baseline and two justified alternatives for ${raw.title.toLowerCase()} under controlled data, evaluation, safety, latency, and cost conditions.` ,
    researchQuestion: raw.researchQuestion || `Which approach provides the strongest decision value for ${raw.title.toLowerCase()}, and under what conditions would the recommendation change?`,
    portfolioTitle: raw.portfolioTitle || `Portfolio Artifact — ${raw.title} Decision System`,
    portfolioDescription: raw.portfolioDescription || `Create an employer-ready project that demonstrates ${raw.title.toLowerCase()} through reproducible code, evaluation, controls, monitoring, and executive communication.` ,
    growthIndicators: raw.growthIndicators || [
      { title: "Decision Framer", description: "You connect technical work to a named user, action, cost, and consequence." },
      { title: "Evidence Builder", description: "You create baselines, controlled comparisons, tests, and reproducible artifacts." },
      { title: "Risk Reviewer", description: "You examine uncertainty, subgroups, misuse, privacy, security, and failure behavior." },
      { title: "Portfolio Communicator", description: "You explain architecture, results, limits, operations, and business value clearly." },
    ],
    reflection: raw.reflection || raw.investigationQuestions || ["What decision is supported?", "What is the baseline?", "Which assumption is weakest?", "Where could leakage occur?", "Which subgroup needs review?", "What happens on failure?", "What must be monitored?", "Who can stop the system?", "What evidence would reverse the recommendation?", "Can another person reproduce the result?"],
    summary: raw.summary || [
      raw.bigIdea,
      ...raw.topics.map((topic) => `${topic} requires an explicit contract, reproducible implementation, and measured validation.`),
      "Baselines make complexity accountable.",
      "Independent evidence protects against optimistic development claims.",
      "Privacy, fairness, security, human oversight, latency, and cost belong in technical design.",
      "A professional artifact includes code, tests, evidence, limitations, ownership, monitoring, and a runbook.",
    ],
    lumineryMessage: raw.lumineryMessage || `Build ${raw.title.toLowerCase()} from a clear decision, prove it with independent evidence, and never hide uncertainty or operational risk.` ,
    mentorRoles: raw.mentorRoles || profile.roles,
  };
}

